const encodePath = p => p.split("/").map(encodeURIComponent).join("/");

function tracksFor(folder) {
    return folder ? manifest.folders[folder] || [] : manifest.musics;
}

function trackUrl(folder, file) {
    return encodePath(folder ? `musics/${folder}/${file}` : `musics/${file}`);
}

function songRow(file) {
    return `<li>
        <img class="invert" src="music.svg" width="40px" alt="">
        <div class="info">
            <div>${file}</div>
        </div>
        <div>Unknown</div>
        <div class="playnow">
            <div>play now</div>
            <div class="playnowimg"><img class="invert" src="musicplayer.svg" alt=""></div>
        </div>
    </li>`;
}

function renderSongList(folder) {
    songul.innerHTML = "";
    for (const file of tracksFor(folder)) {
        songul.innerHTML += songRow(file);
    }
    Array.from(songul.getElementsByTagName("li")).forEach((li, index) => {
        li.addEventListener("click", () => playmusic(folder, index));
    });
}

const playmusic = (folder, index, pause = false) => {
    const tracks = tracksFor(folder);
    const file = tracks[index];
    if (!file) {
        console.warn(`No track at index ${index} in ${folder || "/musics"}`);
        return;
    }

    currentFolder = folder;
    playlist = tracks;
    currentIndex = index;

    currentsong.src = "/" + trackUrl(folder, file);
    document.querySelector(".songinfo").innerHTML = file;
    document.querySelector(".playtime").innerHTML = "00:00";

    if (pause) {
        playBtn.src = "musicplayer.svg";
        return;
    }

    currentsong.play().catch(err => {
        console.error(`Could not play ${file}:`, err);
        playBtn.src = "musicplayer.svg";
    });
    playBtn.src = "pause.svg";
};

async function loadManifest() {
    const res = await fetch("/songs.json", { cache: "no-cache" });
    if (!res.ok) throw new Error(`songs.json -> ${res.status}`);
    manifest = await res.json();
    manifest.folders = manifest.folders || {};
    manifest.musics = manifest.musics || [];
}

